<?php
function rwForm(string $action,array $r=[]):void{echo '<form method="post" enctype="multipart/form-data">';csrf();echo '<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.(int)($r['id']??0).'"><input type="hidden" name="revision" value="'.(int)($r['revision']??0).'">';}
function rwProjectWorkspace(array $u,array $r):void{
 $manager=researchManager($u);$owner=(int)$r['student_id']===(int)$u['id'];$supervisor=(int)$r['supervisor_id']===(int)$u['id'];$pl=rwPL($u,$r);$full=$manager||$owner||$supervisor||$pl;$ms=rwMilestones($r);if(!$full)$ms=array_values(array_filter($ms,fn($m)=>$m['evaluator_visible']));$done=count(array_filter($ms,fn($m)=>rwStatus($r,$m)[0]==='Completed'));$progress=count($ms)?round(100*$done/count($ms)):0;
 ?><section class="card rw-overview" id="milestones"><div class="heading"><div><span class="eyebrow">SHARED RESEARCH TIMELINE</span><h2><?=$full?'Project progress':'Evaluation workspace'?></h2></div><strong><?=$progress?>% completed</strong></div><progress max="100" value="<?=$progress?>"></progress><p><?=$done?> of <?=count($ms)?> milestones completed. Dates use Bhutan time.</p><?php if(!$ms):?><p class="notice">DAA has not published the milestone timeline for this registration period.</p><?php else:?><div class="table-wrap"><table class="ac-bordered rw-timeline"><thead><tr><th>Activity / phase</th><th>Dates</th><th>Your action</th><th>Status</th><th>Open</th></tr></thead><tbody><?php foreach($ms as $m):[$state,$tone]=rwStatus($r,$m);?><tr class="rw-<?=$tone?>"><td><b><?=e($m['title'])?></b><small><?=e($m['phase'])?></small></td><td><?=e($m['start_date'])?> – <?=e($m['due_date'])?><small><?=e(date('l',strtotime($m['due_date'])))?></small></td><td><?=e($owner?$m['student_action']:($supervisor?$m['supervisor_action']:($full?$m['coordinator_action']:'Review and return the assigned research paper')))?></td><td><span class="badge"><?=e($state)?></span></td><td><a href="#milestone-<?=$m['id']?>">Open activity</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
 <?php foreach($ms as $m):?><section class="card" id="milestone-<?=$m['id']?>"><details><summary><?=e($m['sequence_no'].'. '.$m['title'])?> · <?=e($m['due_date'])?></summary><p><b>Student:</b> <?=e($m['student_action'])?><br><b>Supervisor:</b> <?=e($m['supervisor_action'])?><br><b>DAA:</b> <?=e($m['coordinator_action'])?></p><?php rwForm('rw_work',$r);?><input type="hidden" name="milestone_id" value="<?=$m['id']?>"><div class="form-grid"><label>Action<select name="kind"><option>Comment</option><?php if($owner&&in_array($r['status'],['Approved','Completed'],true)):?><option>Submission</option><option>Resubmission</option><?php endif;if($supervisor||$manager||(!$full&&$m['evaluator_visible'])):?><option>Returned feedback</option><?php endif;if($supervisor||$manager):?><option>Completed</option><?php endif;?></select></label><label>Document (DOCX / PDF, maximum 20 MB)<input type="file" name="document" accept=".docx,.pdf"></label><label class="full">Comments / instructions<textarea name="comments" rows="3" required></textarea></label></div><button>Save and notify participants</button></form><h3>Submission and review history</h3><div class="table-wrap"><table><tr><th>Date</th><th>Person</th><th>Action</th><th>Comments</th><th>Document version</th></tr><?php foreach(all('SELECT w.*,u.name FROM research_work w JOIN users u ON u.id=w.actor_id WHERE project_id=? AND milestone_id=? ORDER BY w.id DESC',[$r['id'],$m['id']])as $w):?><tr><td><?=e($w['created_at'])?></td><td><?=e($w['name'])?></td><td><?=e($w['kind'])?></td><td><?=nl2br(e($w['comments']))?></td><td><?php if($w['file_key']):?><a href="?page=rw_download&amp;file=<?=$w['id']?>"><?=e($w['file_name'])?></a><?php endif;?></td></tr><?php endforeach;?></table></div></details></section><?php endforeach;?>
 <?php if($manager||$pl):?><section class="card"><h2>Assignments</h2><?php rwForm('rw_assign',$r);?><div class="form-grid"><label>Assignment<select name="assignment"><option value="supervisor">Assign / replace supervisor</option><?php if($manager):?><option value="evaluator">Add internal evaluator</option><?php endif;?></select></label><label>Teaching staff<select name="teacher_id" required><option value="">Select…</option><?php foreach(all("SELECT id,name,department FROM users WHERE active=1 AND role IN ('faculty','hod','pl','daa') ORDER BY name")as $t):if(!$manager&&$t['department']!==$r['department'])continue;?><option value="<?=$t['id']?>"><?=e($t['name'].' · '.$t['department'])?></option><?php endforeach;?></select></label><label>Document to share (required for evaluator)<select name="document_id"><option value="">Select submitted document…</option><?php foreach(all("SELECT w.*,u.name FROM research_work w JOIN users u ON u.id=w.actor_id WHERE project_id=? AND file_key<>'' ORDER BY w.id DESC",[$r['id']])as $doc):?><option value="<?=$doc['id']?>"><?=e($doc['created_at'].' · '.$doc['name'].' · '.$doc['file_name'])?></option><?php endforeach;?></select></label><label>Assignment instructions<textarea name="comments" required></textarea></label></div><button>Assign and notify</button></form><p>Evaluators: <?=e(implode(', ',array_column(all('SELECT u.name FROM research_evaluators e JOIN users u ON u.id=e.user_id WHERE e.project_id=?',[$r['id']]),'name')))?></p></section><?php endif;?>
 <?php if($manager||$supervisor||$pl):?><section class="card"><h2>Research grades</h2><?php if($manager||$supervisor):rwForm('rw_grade',$r);?><div class="form-grid"><label>Secured marks<input type="number" name="secured" step="any" min="0" required></label><label>Out of<input type="number" name="maximum" step="any" min="0.0001" required></label><label>Weighting (%)<input type="number" name="weighting" step="any" min="0.0001" max="100" required></label><label>Comments<textarea name="comments" required></textarea></label></div><button>Submit grades to PL and DAA</button></form><?php endif;?><table><tr><th>Supervisor</th><th>Secured / maximum</th><th>Weighting</th><th>Weighted score</th><th>Comments</th></tr><?php foreach(all('SELECT g.*,u.name FROM research_grades g JOIN users u ON u.id=g.actor_id WHERE project_id=?',[$r['id']])as $g):?><tr><td><?=e($g['name'])?></td><td><?=e($g['secured'].' / '.$g['maximum'])?></td><td><?=e($g['weighting'])?>%</td><td><?=number_format($g['secured']/$g['maximum']*$g['weighting'],2)?></td><td><?=e($g['comments'])?></td></tr><?php endforeach;?></table></section><?php endif;
}
function rwDashboard(array $u):void{
 $projects=all('SELECT p.*,s.name AS student_name,t.name AS supervisor_name,rs.programme FROM research_projects p JOIN users s ON s.id=p.student_id JOIN users t ON t.id=p.supervisor_id LEFT JOIN research_students rs ON rs.user_id=p.student_id ORDER BY p.id DESC');$projects=array_values(array_filter($projects,fn($r)=>researchCanView($u,$r)));$total=0;$done=0;$review=0;$soon=0;$groups=[];
 foreach($projects as &$r){$ms=rwMilestones($r);if(!researchManager($u)&&!rwPL($u,$r)&&(int)$r['student_id']!==(int)$u['id']&&(int)$r['supervisor_id']!==(int)$u['id'])$ms=array_values(array_filter($ms,fn($m)=>$m['evaluator_visible']));$r['milestones']=count($ms);$r['completed']=0;foreach($ms as $m){[$state,$tone]=rwStatus($r,$m);$total++;if($tone==='done'){$done++;$r['completed']++;}if($tone==='review')$review++;if($m['due_date']>=date('Y-m-d')&&$m['due_date']<=date('Y-m-d',strtotime('+30 days'))&&$tone!=='done')$soon++;}foreach(['Supervisor'=>$r['supervisor_name'],'Department'=>$r['department'],'Programme'=>$r['programme']??'Unspecified']as $kind=>$name){$key=$kind.' · '.$name;$groups[$key]['done']=($groups[$key]['done']??0)+$r['completed'];$groups[$key]['total']=($groups[$key]['total']??0)+$r['milestones'];}}unset($r);
 ?><div class="rw-shell"><aside class="rw-sidebar"><h2>ResearchTrack</h2><p>Research management</p><a href="#rw-dashboard">Dashboard</a><a href="#rw-projects">My Projects</a><a href="#rw-progress">Milestone Tracker</a><a href="#rw-projects">Documents</a><a href="#rw-projects">Reviews &amp; Feedback</a><?php if(researchManager($u)):?><a href="#rw-timelines">Timeline management</a><?php endif;?><a href="?page=rw_access&amp;register=1">Student registration</a></aside><div class="rw-main" id="rw-dashboard"><span class="eyebrow">RESEARCH WORKSPACE / REVIEWS &amp; FEEDBACK</span><h1><?=researchManager($u)?'Research Overview':(researchStudent($u)?'My Research Overview':'Supervision Overview')?></h1><p>Track milestones, submissions and important deadlines.</p><div class="stats"><div><small>Total milestones</small><strong><?=$total?></strong></div><div><small>Completed</small><strong><?=$done?></strong></div><div><small>Awaiting review</small><strong><?=$review?></strong></div><div><small>Upcoming deadlines · 30 days</small><strong><?=$soon?></strong></div></div><section class="card" id="rw-progress"><h2>Research progress</h2><progress max="100" value="<?=$total?round(100*$done/$total):0?>"></progress><p><?=$total?round(100*$done/$total):0?>% of published milestones completed</p><div class="rw-phases"><span>01 · Proposal development</span><span>02 · Research &amp; drafts</span><span>03 · Evaluation &amp; defense</span><span>04 · Final submission</span></div></section><section class="card" id="rw-projects"><h2>Projects and submissions</h2><div class="table-wrap"><table><tr><th>Project / student</th><th>Programme</th><th>Supervisor</th><th>Status</th><th>Progress</th></tr><?php foreach($projects as $r):?><tr><td><a href="?page=research&amp;id=<?=$r['id']?>"><?=e($r['title'])?></a><small><?=e($r['student_name'])?></small></td><td><?=e($r['programme']??'')?></td><td><?=e($r['supervisor_name'])?></td><td><?=e($r['status'])?></td><td><progress max="<?=max(1,$r['milestones'])?>" value="<?=$r['completed']?>"></progress><small><?=$r['completed']?> / <?=$r['milestones']?></small></td></tr><?php endforeach;?></table></div></section><?php if(!researchStudent($u)):?><section class="card"><h2>Progress by supervisor, department and programme</h2><div class="rw-progress-groups"><?php foreach($groups as $label=>$g):?><div><b><?=e($label)?></b><progress max="<?=max(1,$g['total'])?>" value="<?=$g['done']?>"></progress><small><?=$g['done']?> / <?=$g['total']?> milestones completed</small></div><?php endforeach;?></div></section><?php endif;?></div></div>
 <?php if(researchManager($u)):?><section class="card" id="rw-timelines"><h2>Publish a shared research timeline</h2><p>Choose the starting year for the July–June research cycle. Review dates before publishing. The 2025/2026 source is a template; weekdays are calculated from the chosen dates. Uploading a CSV updates matching sequence numbers and retains existing activity history.</p><a class="button secondary" href="?page=rw_timeline_csv&amp;year=<?=date('Y')?>">Download timeline template for <?=date('Y')?>/<?=date('Y')+1?></a><?php rwForm('rw_timeline');?><div class="form-grid"><label>Registration period<select name="period_id" required><?php foreach(all('SELECT * FROM research_periods ORDER BY id DESC')as $p):?><option value="<?=$p['id']?>"><?=e($p['title'].' · '.$p['department'])?></option><?php endforeach;?></select></label><label>Starting academic year<input type="number" name="year" min="2020" max="2100" value="<?=date('Y')?>"></label><label>Timeline CSV (optional when using template)<input type="file" name="timeline" accept=".csv"></label></div><label class="period-delete-confirm"><input type="checkbox" name="template" value="1"><span>Use the standard 24-milestone template for the selected academic year instead of a CSV.</span></label><button>Publish timeline</button></form><?php foreach(all('SELECT * FROM research_periods ORDER BY id DESC')as $p):?><p><a href="?page=rw_timeline_csv&amp;period=<?=$p['id']?>">Export <?=e($p['title'].' · '.$p['department'])?></a></p><?php endforeach;?></section><?php endif;
}
